import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.7w-lhQN6.js";const h=JSON.parse('{"title":"설정","description":"","frontmatter":{},"headers":[],"relativePath":"ko/reference/configuration.md","filePath":"ko/reference/configuration.md","lastUpdated":1793550481000}'),r={name:"ko/reference/configuration.md"};function a(n,t,s,l,i,u){return e(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="설정" tabindex="-1">설정 <a class="header-anchor" href="#설정" aria-label="Permalink to &quot;설정&quot;">​</a></h1><p>이 문서는 MCP Lens가 데이터를 어디에 저장하는지와 VS Code 확장 설정 전체를 정리한다. walkthrough를 다시 뒤지지 않고도 키나 경로를 바로 찾을 수 있다. 무엇을 왜 바꿔야 하는지는 <a href="/MCPLens/ko/guide/vscode-extension">VS Code 확장</a>과 <a href="/MCPLens/ko/guide/global-actions">전역 조치</a>를 본다.</p><h2 id="데이터-위치" tabindex="-1">데이터 위치 <a class="header-anchor" href="#데이터-위치" aria-label="Permalink to &quot;데이터 위치&quot;">​</a></h2><p>MCP Lens가 보관하는 모든 것은 <code>~/.mcplens</code> 아래에 있다. 프로젝트 안이나 클라이언트 자체의 설정·로그에는 절대 쓰지 않는다.</p><table tabindex="0"><thead><tr><th>경로</th><th>내용</th></tr></thead><tbody><tr><td><code>~/.mcplens/lens.db</code></td><td>SQLite 데이터베이스. 스캔된 툴 정의, 훅으로 관측한 호출, 세션을 담는다.</td></tr><tr><td><code>~/.mcplens/inbox</code></td><td>확장이나 CLI가 데이터베이스로 옮기기 전에 대기하는 훅 이벤트 큐.</td></tr><tr><td><code>~/.mcplens/db-writer.lock</code></td><td>확장과 CLI가 동시에 쓰지 않도록 막는 writer lease 파일.</td></tr><tr><td><code>~/.mcplens/oauth</code></td><td>인증된 MCP 서버의 OAuth 토큰과 클라이언트 등록 정보. 소유자만 읽을 수 있는 파일 권한으로 기록된다.</td></tr></tbody></table><h2 id="확장-설정" tabindex="-1">확장 설정 <a class="header-anchor" href="#확장-설정" aria-label="Permalink to &quot;확장 설정&quot;">​</a></h2><p>VS Code Settings UI에서 <code>MCP Lens</code>를 검색해 열거나, <code>settings.json</code>을 직접 편집한다.</p><table tabindex="0"><thead><tr><th>설정</th><th>타입</th><th>기본값</th><th>의미</th></tr></thead><tbody><tr><td><code>mcpLens.reportDays</code></td><td>number</td><td><code>30</code></td><td>상태 표시줄 요약과 리포트가 집계하는 기간(일).</td></tr><tr><td><code>mcpLens.reportDetail</code></td><td><code>summary</code> | <code>full</code></td><td><code>summary</code></td><td><strong>MCP Lens: Show Report</strong> 커맨드의 상세 수준. <code>summary</code>는 후보·정상 툴 목록을 5개로 제한한다. 조치나 점검이 필요한 항목은 어느 값이든 항상 전체가 표시된다.</td></tr><tr><td><code>mcpLens.autoScan</code></td><td><code>prompt</code> | <code>always</code> | <code>never</code></td><td><code>never</code></td><td>새 서버가 감지됐을 때 자동 스캔 여부. <code>prompt</code>는 먼저 물어보고, <code>always</code>는 (walkthrough에서 첫 수동 스캔을 한 뒤) 바로 스캔하며, <code>never</code>는 직접 트리거할 때만 스캔한다.</td></tr><tr><td><code>mcpLens.authIgnore</code></td><td>string[]</td><td><code>[]</code></td><td>로그인 요청을 더 이상 표시하지 않을 서버 이름 목록. &quot;Don&#39;t ask for this server&quot; 버튼으로 자동 채워진다.</td></tr><tr><td><code>mcpLens.oauthClients</code></td><td>object</td><td><code>{}</code></td><td>자동 클라이언트 등록을 거부하는 서버용 OAuth 클라이언트 id. 예: <code>{ &quot;github&quot;: &quot;Iv1.abc123&quot; }</code>. 클라이언트 시크릿은 여기 저장되지 않고 <code>~/.mcplens/oauth/clients.json</code>에 들어간다.</td></tr><tr><td><code>mcpLens.unsupportedServers</code></td><td>string[]</td><td><code>[]</code></td><td>Lens가 지원할 수 없다고 판단한 서버 이름(예: 자동 클라이언트 등록을 거부하는 서버). 자동으로 채워지며, 트리에서 숨겨지고 다시 묻지 않는다.</td></tr><tr><td><code>mcpLens.inferenceProvider</code></td><td><code>auto</code> | <code>claude</code> | <code>codex</code></td><td><code>auto</code></td><td>의존성 분석에 쓰는 제공자. <code>auto</code>는 두 CLI가 모두 설치되어 있으면 Claude를 고른다. 하나를 명시적으로 고정하려면 이 값을 설정한다.</td></tr><tr><td><code>mcpLens.autoAnalyze</code></td><td>boolean</td><td><code>false</code></td><td>자동 스캔 뒤 새 툴을 제공자 CLI로 분석해서 각각 독립적으로 꺼도 되는지 판단한다. 이는 제공자의 토큰을 소모하며 툴 정의와 사용량 카운트를 그쪽으로 보낸다. walkthrough에서 한 번 동의하기 전에는 절대 실행되지 않는다.</td></tr><tr><td><code>mcpLens.claudeModel</code></td><td>string</td><td><code>haiku</code></td><td>의존성 분석에 쓰는 Claude 모델.</td></tr><tr><td><code>mcpLens.codexModel</code></td><td>string</td><td><code>gpt-5.6-luna</code></td><td>의존성 분석에 쓰는 Codex 모델.</td></tr><tr><td><code>mcplens.dependencyAnalysis.rollout</code></td><td><code>off</code> | <code>claude</code> | <code>codex</code> | <code>all</code></td><td><code>off</code></td><td>전역 조치(사용하지 않는 툴을 해당 클라이언트의 설정 파일을 편집해 끄는 것)를 어느 클라이언트가 쓸 수 있는지. 분석·캐시·상세 보기는 <code>off</code>를 포함한 모든 값에서 계속 쓸 수 있다. Gemini CLI는 여기서 절대 허용되지 않는다. 전역 조치가 이를 지원하지 않는다.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">참고</p><p><code>mcplens.dependencyAnalysis.rollout</code>은 이 문서의 다른 모든 키와 다른(소문자) 설정 네임스페이스를 쓴다. 오타가 아니라 VS Code가 실제로 읽는 정확한 키다. <code>settings.json</code>에 직접 설정한다면 대소문자를 다시 한번 확인한다.</p></div>',9)])])}const m=d(r,[["render",a]]);export{h as __pageData,m as default};
